const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const P = [];
for (let i = 0; i < 7; i++) {
  P.push({ x: input[2 * i], y: input[2 * i + 1] });
}

function sub(a, b) {
  return { x: a.x - b.x, y: a.y - b.y };
}

function dot(a, b) {
  return a.x * b.x + a.y * b.y;
}

function cross(a, b, c) {
  return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

function dist2(a, b) {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  return dx * dx + dy * dy;
}

let valid = true;

// 1. Ângulo ∠P2P1P3 agudo
if (dot(sub(P[1], P[0]), sub(P[2], P[0])) <= 0) valid = false;

// 2. P1P2 == P1P3
if (dist2(P[0], P[1]) !== dist2(P[0], P[2])) valid = false;

// 3. P2, P3, P4, P5 colineares
if (cross(P[1], P[2], P[3]) !== 0 || cross(P[1], P[2], P[4]) !== 0) valid = false;

// 4. Pontos médios de P2P3 e P4P5 coincidem
if (P[1].x + P[2].x !== P[3].x + P[4].x || P[1].y + P[2].y !== P[3].y + P[4].y) valid = false;

// 5. P2P3 > P4P5
if (dist2(P[1], P[2]) <= dist2(P[3], P[4])) valid = false;

// 6. P4P6 e P5P7 perpendiculares a P2P3
const base = sub(P[2], P[1]); // P3 - P2
if (dot(sub(P[5], P[3]), base) !== 0) valid = false;
if (dot(sub(P[6], P[4]), base) !== 0) valid = false;

// 7. P4P6 == P5P7
if (dist2(P[3], P[5]) !== dist2(P[4], P[6])) valid = false;

// 8. P1 e P6 separados pela reta P2P3
const cross1 = cross(P[1], P[2], P[0]);
const cross6 = cross(P[1], P[2], P[5]);
if (!((cross1 > 0 && cross6 < 0) || (cross1 < 0 && cross6 > 0))) valid = false;

console.log(valid ? 'S' : 'N');
